// Intelligente Erkennung: Audio oder Text?
const keywords = $input.first().json.message.content; // Von "Message a model"
const messageDate = new Date($('Telegram Sprachnachricht Empfang').first().json.message.date * 1000);
const userName = $('Telegram Sprachnachricht Empfang').first().json.message.from.first_name;
const originalMessage = $('Telegram Sprachnachricht Empfang').first().json.message;

// Prüfe ob es eine Sprachnachricht war
const isVoiceMessage = originalMessage.voice !== undefined;

let originalText;
let messageType;

if (isVoiceMessage) {
  // Sprachnachricht: Text von Whisper holen
  originalText = $('OpenAI Whisper Transkription').first().json.text;
  messageType = "🎤 Sprachnachricht";
} else {
  // Textnachricht: Text direkt aus der Telegram-Nachricht
  originalText = originalMessage.text;
  messageType = "💬 Textnachricht";
}

// Deutsche Formatierung mit Schweizer Zeitzone
const formattedDate = messageDate.toLocaleString('de-CH', {
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  timeZone: 'Europe/Zurich'
});

// Format: Datum, Typ, Schlagworte, Text
const formattedText = `\n\n📅 ${formattedDate} (${messageType})\n🏷️ Schlagworte: ${keywords}\n📝 Inhalt: ${originalText}`;

return [{
  json: {
    formattedText: formattedText,
    originalText: originalText,
    keywords: keywords,
    timestamp: formattedDate,
    userName: userName,
    messageType: isVoiceMessage ? 'voice' : 'text'
  }
}];

